#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Projectiles;
using MVZ2.Vanilla.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.projectileChill)]
    public class ChillProjectileBehaviour : EntityBehaviourDefinition
    {
        public ChillProjectileBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(Entity projectile)
        {
            base.Update(projectile);
            // 更新模型。
            projectile.SetAnimationBool("Chill", projectile.HasBuff<ChillProjectileBuff>());
        }
    }
}
